async update(
  id: UserId,
  mutator: (u: User) => Result<User, UserError>,
): Promise<Result<User, RepositoryError | UserError>> {
  try {
    return await this.prisma.$transaction<Result<User, RepositoryError | UserError>>(async (tx) => {
      const locked = await tx.$queryRaw<RawUserRow[]>`
        SELECT u.id, COALESCE(w.balance_tokens, 0)::int AS token_balance, u.language
        FROM users u LEFT JOIN wallets w ON w.user_id = u.id WHERE u.id = ${id}::uuid FOR UPDATE OF u
      `;
      if (locked.length === 0) return Err({ type: 'not_found', id });
      const row = locked[0]!;
      const hydrated = this.hydrateRow(row.id as UserId, row.token_balance, row.language);
      if (!hydrated.ok) return hydrated;
      const mutated = mutator(hydrated.value);
      if (!mutated.ok) return Err(mutated.error);
      await tx.user.update({ where: { id }, data: { language: mutated.value.language } });
      return Ok(mutated.value);
    });
  } catch (e) {
    if ((e as { code?: string })?.code === 'P2034') {
      return Err({ type: 'concurrent_modification', id, detail: extractMessage(e) });
    }
    return Err({ type: 'db_error', detail: extractMessage(e), cause: e });
  }
}
